import org.jfree.data.time.Second;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class TimeSeries_createCopy_TriageGen0Test {

    private TimeSeries series;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");
        // Add some dummy data
        series.add(new Second(new java.util.Date(1000L)), 10.0);
        series.add(new Second(new java.util.Date(2000L)), 20.0);
        series.add(new Second(new java.util.Date(3000L)), 30.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopy_StartNegative() throws CloneNotSupportedException {
        series.createCopy(-1, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopy_EndLessThanStart() throws CloneNotSupportedException {
        series.createCopy(2, 1);
    }

    @Test
    public void testCreateCopy_ValidRange() throws CloneNotSupportedException {
        // Test copying items from index 1 to 2
        TimeSeries copy = series.createCopy(1, 2);

        assertNotNull(copy);
        assertEquals("Name should be preserved", series.getKey(), copy.getKey());
        assertEquals("Item count should match range", 2, copy.getItemCount());

        // Verify values
        assertEquals(20.0, copy.getValue(0).doubleValue(), 0.001);
        assertEquals(30.0, copy.getValue(1).doubleValue(), 0.001);

        // Verify min/max are reset to NaN as per implementation
        assertTrue(Double.isNaN(copy.getMinY()));
        assertTrue(Double.isNaN(copy.getMaxY()));

        // Verify deep copy (modifying copy shouldn't change original)
        copy.add(new Second(new java.util.Date(4000L)), 40.0);
        assertEquals(3, series.getItemCount());
        assertEquals(3, copy.getItemCount());
    }

    @Test
    public void testCreateCopy_SingleItem() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(0, 0);
        assertEquals(1, copy.getItemCount());
        assertEquals(10.0, copy.getValue(0).doubleValue(), 0.001);
    }

    @Test
    public void testCreateCopy_FullRange() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(0, series.getItemCount() - 1);
        assertEquals(series.getItemCount(), copy.getItemCount());
    }

    @Test
    public void testCreateCopy_EmptySeries() throws CloneNotSupportedException {
        TimeSeries emptySeries = new TimeSeries("Empty");
        // The implementation uses index loop: for (int index = start; index <= end; index++)
        // If start=0, end=0 on empty series, it will throw IndexOutOfBoundsException
        // because this.data.get(index) will fail.
        try {
            emptySeries.createCopy(0, 0);
        } catch (IndexOutOfBoundsException e) {
            // This is expected behavior given the provided source code logic
        }
    }

    @Test
    public void testCreateCopy_DataSizeCheck() throws CloneNotSupportedException {
        // The code has: if (this.data.size() >= 0)
        // Since size is never < 0, this branch is always taken.
        // We test the logic where we copy the whole range.
        TimeSeries copy = series.createCopy(0, 2);
        assertEquals(3, copy.getItemCount());
    }
}
